create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id,display_name) values (new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))); return new; end; $$;
revoke execute on function public.handle_new_user() from public;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.record_offer_redirect(p_offer_id uuid,p_referrer text default null,p_user_agent text default null) returns void language plpgsql security definer set search_path = public as $$ declare merchant uuid; begin select merchant_id into merchant from public.offers where id=p_offer_id and status='active'; if merchant is null then return; end if; insert into public.redirect_events(offer_id,merchant_id,visitor_hash,referrer,user_agent) values(p_offer_id,merchant,encode(digest(coalesce(p_user_agent,'') || coalesce(p_referrer,''),'sha256'),'hex'),left(p_referrer,500),left(p_user_agent,500)); end; $$;
revoke execute on function public.record_offer_redirect(uuid,text,text) from public;
grant execute on function public.record_offer_redirect(uuid,text,text) to anon,authenticated;
